from __future__ import annotations
from app.database_support import *

class DatabaseMixin5Part3:

    async def _ensure_contract_economy_schema_part_3(self, db: aiosqlite.Connection) -> None:
        await aiosqlite.execute_backend_ddl(db, sqlite_sql='\n                CREATE TABLE IF NOT EXISTS contract_reward_budgets (\n                    guild_id INTEGER NOT NULL,\n                    budget_key TEXT NOT NULL,\n                    period_key TEXT NOT NULL,\n                    limit_amount INTEGER NOT NULL,\n                    reserved_amount INTEGER NOT NULL DEFAULT 0,\n                    spent_amount INTEGER NOT NULL DEFAULT 0,\n                    updated_at TEXT NOT NULL,\n                    PRIMARY KEY (guild_id,budget_key,period_key)\n                )\n            ', mysql_sql='\n                CREATE TABLE IF NOT EXISTS contract_reward_budgets (\n                    guild_id BIGINT UNSIGNED NOT NULL,\n                    budget_key VARCHAR(64) NOT NULL,\n                    period_key VARCHAR(32) NOT NULL,\n                    limit_amount DECIMAL(65,0) NOT NULL,\n                    reserved_amount DECIMAL(65,0) NOT NULL DEFAULT 0,\n                    spent_amount DECIMAL(65,0) NOT NULL DEFAULT 0,\n                    updated_at VARCHAR(64) NOT NULL,\n                    PRIMARY KEY (guild_id,budget_key,period_key)\n                ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci\n            ')
        await aiosqlite.execute_backend_ddl(db, sqlite_sql="\n                CREATE TABLE IF NOT EXISTS contract_source_state (\n                    contract_id INTEGER PRIMARY KEY,\n                    guild_id INTEGER NOT NULL,\n                    source_key TEXT NOT NULL,\n                    source_label TEXT NOT NULL,\n                    target_user_id INTEGER NOT NULL DEFAULT 0,\n                    budget_key TEXT NOT NULL DEFAULT '',\n                    budget_period TEXT NOT NULL DEFAULT '',\n                    eligibility_json TEXT NOT NULL DEFAULT '{}',\n                    modifier_json TEXT NOT NULL DEFAULT '[]',\n                    created_at TEXT NOT NULL,\n                    UNIQUE(guild_id,source_key,budget_period,target_user_id),\n                    FOREIGN KEY (contract_id) REFERENCES contracts(contract_id) ON DELETE CASCADE\n                )\n            ", mysql_sql="\n                CREATE TABLE IF NOT EXISTS contract_source_state (\n                    contract_id BIGINT UNSIGNED NOT NULL,\n                    guild_id BIGINT UNSIGNED NOT NULL,\n                    source_key VARCHAR(64) NOT NULL,\n                    source_label VARCHAR(120) NOT NULL,\n                    target_user_id BIGINT UNSIGNED NOT NULL DEFAULT 0,\n                    budget_key VARCHAR(64) NOT NULL DEFAULT '',\n                    budget_period VARCHAR(32) NOT NULL DEFAULT '',\n                    eligibility_json LONGTEXT NOT NULL,\n                    modifier_json LONGTEXT NOT NULL,\n                    created_at VARCHAR(64) NOT NULL,\n                    PRIMARY KEY (contract_id),\n                    UNIQUE KEY uq_contract_source_cycle (guild_id,source_key,budget_period,target_user_id),\n                    KEY idx_contract_source_target (guild_id,target_user_id,source_key),\n                    CONSTRAINT fk_contract_source_contract FOREIGN KEY (contract_id) REFERENCES contracts (contract_id)\n                        ON UPDATE CASCADE ON DELETE CASCADE\n                ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci\n            ")
        await aiosqlite.execute_backend_ddl(db, sqlite_sql="\n                CREATE TABLE IF NOT EXISTS contract_telemetry (\n                    telemetry_id INTEGER PRIMARY KEY AUTOINCREMENT,\n                    guild_id INTEGER NOT NULL,\n                    event_key TEXT NOT NULL,\n                    event_type TEXT NOT NULL,\n                    contract_id INTEGER,\n                    actor_id INTEGER,\n                    counterparty_id INTEGER,\n                    source_key TEXT NOT NULL DEFAULT '',\n                    reward_amount INTEGER NOT NULL DEFAULT 0,\n                    details_json TEXT NOT NULL DEFAULT '{}',\n                    created_at TEXT NOT NULL,\n                    UNIQUE(guild_id,event_key)\n                )\n            ", mysql_sql="\n                CREATE TABLE IF NOT EXISTS contract_telemetry (\n                    telemetry_id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,\n                    guild_id BIGINT UNSIGNED NOT NULL,\n                    event_key VARCHAR(190) NOT NULL,\n                    event_type VARCHAR(48) NOT NULL,\n                    contract_id BIGINT UNSIGNED NULL,\n                    actor_id BIGINT UNSIGNED NULL,\n                    counterparty_id BIGINT UNSIGNED NULL,\n                    source_key VARCHAR(64) NOT NULL DEFAULT '',\n                    reward_amount DECIMAL(65,0) NOT NULL DEFAULT 0,\n                    details_json LONGTEXT NOT NULL,\n                    created_at VARCHAR(64) NOT NULL,\n                    PRIMARY KEY (telemetry_id),\n                    UNIQUE KEY uq_contract_telemetry_event (guild_id,event_key),\n                    KEY idx_contract_telemetry_type (guild_id,event_type,created_at),\n                    KEY idx_contract_telemetry_contract (guild_id,contract_id,telemetry_id)\n                ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci\n            ")
